const items = $input.all();

const results = [];

for (const item of items) {
  const c = item.json;

  const message = c.commit?.message ?? "";
  const title = message.split("\n")[0].trim();
  const lower = message.toLowerCase();

  let evidenceType = "activity";
  let importance = "low";

  if (
    lower.includes("fix") ||
    lower.includes("bug") ||
    lower.includes("error") ||
    lower.includes("issue")
  ) {
    evidenceType = "problem_resolution";
    importance = "high";
  }

  if (
    lower.includes("decision") ||
    lower.includes("decide") ||
    lower.includes("chosen") ||
    lower.includes("use ") ||
    lower.includes("switch")
  ) {
    evidenceType = "decision_signal";
    importance = "high";
  }

  if (
    lower.includes("todo") ||
    lower.includes("pending") ||
    lower.includes("remaining") ||
    lower.includes("next")
  ) {
    evidenceType = "pending_work";
    importance = "high";
  }

  if (
    lower.includes("remove") ||
    lower.includes("delete") ||
    lower.includes("deprecated")
  ) {
    evidenceType = "change";
    importance = "medium";
  }

  results.push({
    json: {
      evidence_id: `github-${c.sha}`,
      source: "github",
      evidence_type: evidenceType,
      importance,
      event_type: "commit",
      event_id: c.sha ?? null,
      timestamp: c.commit?.author?.date ?? null,
      author: c.author?.login ?? c.commit?.author?.name ?? null,
      title,
      content: message,
      url: c.html_url ?? null,
      repository: "priyanshukumarverma091-hub/RETRO-AI",
      extraction: {
        problem_signal:
          evidenceType === "problem_resolution",
        decision_signal:
          evidenceType === "decision_signal",
        pending_work_signal:
          evidenceType === "pending_work"
      }
    }
  });
}

return results;

const items = $input.all();

const evidence = items.map(item => item.json);

const highImportance = evidence.filter(
  e => e.importance === "high"
);

const decisions = evidence.filter(
  e => e.evidence_type === "decision_signal"
);

const pending = evidence.filter(
  e => e.evidence_type === "pending_work"
);

return [
  {
    json: {
      status: "evidence_extracted",
      total_evidence: evidence.length,
      high_importance: highImportance.length,
      decision_signals: decisions.length,
      pending_work_signals: pending.length,
      evidence,
      decisions,
      pending_work: pending
    }
  }
];
